<style>
.lith-sidebar-commands-grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(105px, 1fr));
	/* First number is row gap (vertical), second is column gap (horizontal) */
	gap: 4px 2px; 
	justify-items: center;
	align-items: center;
	text-align: center;
}

/* THE FLATTENER: Forces every hidden wrapper div to center its contents 
   Modified to only target the tool items and their immediate wrappers to avoid breaking dropdowns */
.lith-sidebar-commands-item,
.lith-sidebar-commands-item > div {
	display: flex;
	justify-content: center;
	align-items: center;
	width: 100%;
}

.lith-sidebar-commands-item p {
	margin: 0 !important;
}

/* Button Styling - Restricted to tool buttons to avoid affecting dropdown items */
.lith-sidebar-commands-item > div > button,
.lith-sidebar-commands-item > div > span > button,
.lith-sidebar-commands-item > div > label.tc-btn-invisible {
	display: flex !important;
	flex-wrap: nowrap !important;
	align-items: center;
	justify-content: center;
	gap: 2px; 
	width: 105px !important; 
	max-width: 105px !important; 
	padding: 4px 2px !important;
	margin: 0 !important;
	box-sizing: border-box;
	white-space: nowrap;
	overflow: hidden;
	container-type: inline-size;
}

/* Specific reset for dropdowns inside the tools grid */
.lith-sidebar-commands-item .tc-drop-down {
	display: block !important;
	width: auto !important;
	min-width: 160px;
	text-align: left;
}

.lith-sidebar-commands-item .tc-drop-down button {
	display: block !important;
	width: 100% !important;
	max-width: none !important;
	padding: 4px 8px !important;
	text-align: left;
	font-size: 0.9em !important;
}

.lith-sidebar-commands-item button .tc-btn-text,
.lith-sidebar-commands-item label.tc-btn-invisible .tc-btn-text {
	font-size: clamp(8px, 12cqw, 0.9em) !important; 
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	line-height: 1; 
}
.lith-sidebar-commands-item button svg,
.lith-sidebar-commands-item label.tc-btn-invisible svg {
	flex-shrink: 0;
	width: 1.2em;
	height: 1.2em;
}

/* Fixes Import functionality while removing it from the visual layout flow */
.lith-sidebar-commands-item .tc-file-input-wrapper {
	position: relative;
}
.lith-sidebar-commands-item .tc-file-input-wrapper input[type="file"] {
	position: absolute !important;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	opacity: 0;
	cursor: pointer;
	display: block !important;
}
</style>

