title: $:/lithic/filters/favorite-results.js
type: application/javascript
module-type: filteroperator

Filter operator that returns the results of the topmost favorite tiddler.
\*/
(function(){
"use strict";

exports["favorite-results"] = function(source,operator,options) {
	var favorites = options.wiki.filterTiddlers("[tag[Favorite]]");
	if(favorites.length === 0) {
		return [];
	}
	var topFavorite = favorites[0];
	var tiddler = options.wiki.getTiddler(topFavorite);
	if(tiddler && tiddler.fields.tags && tiddler.fields.tags.indexOf("$:/tags/Filter") !== -1) {
		var filter = tiddler.fields.filter || "";
		if(filter) {
			return options.wiki.filterTiddlers(filter);
		}
	}
	return [topFavorite];
};

})();
"},"$:/lithic/filters/stream-indent.js":{"title":"$:/lithic/filters/stream-indent.js","type":"application/javascript","module-type":"filteroperator","description":"Returns an indented string for each level of depth of a stream node from a given root node, applying indentation to every line within the node","text":"/*\
title: $:/lithic/filters/stream-indent.js
type: application/javascript
module-type: filteroperator
description: Returns an indented string for each level of depth of a stream node from a given root node, applying indentation to every line within the node

Layout: the output is the flat text of the document as it now stands, which is
what Copy Story River puts on the clipboard to paste into a chat, a message or
an agent. Nothing here needs a file behind the document.

  - indentation is read from the stream tree the document is showing (`parent`
    and `stream-list`), never from the absolute indent recorded by the file it
    was imported from (`lithic-indent`). This is the working copy: a node
    re-parented in the streams UI is copied where it now sits. Where nothing has
    been re-indented the two agree, and the copy is then also what the launcher's
    scratch saver writes (serializeScratchWiki in launcher-ui/src/scratch-wiki.ts).
  - one TAB per level, the unit the launcher's parser reads as one level (four
    spaces would read as one too, but a two space indent reads as level zero and
    flattens the whole outline)
  - the blank lines a node was preceded by (`lithic-gap`) are replayed above it,
    so two paragraphs stay two paragraphs on the way back in. That field is the
    only record paragraph separation has, and no streams gesture contradicts it.
  - ONE blank line is the floor between two nodes, whatever the file recorded. A
    node added in the streams UI carries no gap of its own, and on screen it is
    its own block with air around it, so the plaintext copy reads the way the
    document looks. The save is the other half of this and does NOT floor: it
    writes back the file it came from, exactly, so a file that ran two lines
    together saves that way and is copied separated.
  - the node the document OPENS with carries no blank lines above it, and which
    node that is cannot be counted: Copy Story River reaches this operator through
    `:map`, which evaluates its subfilter once per node, so a counter inside the
    operator reads zero for every one of them and no gap would ever replay
    (measured 2026-10-27: a 5,851 character markdown note copied as 5,830
    characters, all 22 of its blank lines gone). The document answers it instead:
    the opening node is the root's first `stream-list` entry, or the root itself
    when the root is the text being copied.
\*/

(function () {

    "use strict";

    /**
     * The first title in a `stream-list`, read without `$tw`: this module is
     * loaded by a test harness as well as by the wiki, and a title holding a
     * space is bracketed in that field.
     */
    function firstListEntry(value) {
        if (!value) return "";
        var match = /^\s*(?:\[\[([^\]]+)\]\]|(\S+))/.exec(value);
        return match ? (match[1] !== undefined ? match[1] : match[2]) : "";
    }

    exports["stream-indent"] = function (source, operator, options) {
        var results = [];
        var rootTitle = operator.operand || "";

        var rootNode = options.wiki.getTiddler(rootTitle);
        var rootIsBlank = (!rootNode || !rootNode.fields.text || rootNode.fields.text.trim() === "");

        // The node the document's own first line belongs to: the one node that
        // opens without a blank line above it, whatever the caller emits first.
        var openingTitle = firstListEntry(rootNode && rootNode.fields["stream-list"]);

        source(function (tiddler, title) {
            var fields = (tiddler && tiddler.fields) ? tiddler.fields : {};

            var depth = 0;
            var current = title;
            // Traverse parents until we hit the root node or a node with no parent
            while (current && current !== rootTitle) {
                var node = options.wiki.getTiddler(current);
                if (!node || !node.fields.parent) break;
                current = node.fields.parent;
                depth++;
                if (depth > 50) break; // safeguard against circular references
            }

            if (rootIsBlank) {
                depth = Math.max(0, depth - 1);
            }

            var text = fields.text ? fields.text : "";

            var gap = parseInt(fields["lithic-gap"], 10);
            if (!isFinite(gap) || gap < 0) gap = 0;
            var opening = (title === rootTitle) || (openingTitle !== "" && title === openingTitle);
            var lead = opening ? "" : new Array(Math.max(gap, 1) + 1).join("\n");

            var pad = new Array(depth + 1).join("\t");
            var indentedText = lead + pad + text.split("\n").join("\n" + pad);
            results.push(indentedText);
        });
        return results;
    };

})();"},"$:/lithic/fonts/katex-numerals":{"title":"$:/lithic/fonts/katex-numerals","type":"text/css","tags":"$:/tags/Stylesheet","text":"/*
SUPERSEDED - kept only so older standalones that imported the previous
