</svg>"},"$:/lithic/macros/calc":{"title":"$:/lithic/macros/calc","module-type":"macro","tags":"","type":"application/javascript","text":"/*\
title: $:/lithic/macros/calc
type: application/javascript
module-type: macro

Macro to evaluate arithmetic.
Usage: 
  <<calc "3+3">>   -> Returns "6" (Plaintext)
  <<calc "3+3=">>  -> Returns "$$ 3+3=6 $$" (KaTeX with formatting)
\*/
(function () {

    /*jslint node: true, browser: true */
    /*global $tw: false */
    "use strict";

    exports.name = "calc";

    exports.params = [
        { name: "equation" }
    ];

    exports.run = function (equation) {
        try {
            // 0. CHECK MODE: Does it end with "="?
            var rawEq = equation.trim();
            var showKatex = false;

            if (rawEq.endsWith("=")) {
                showKatex = true;
                rawEq = rawEq.slice(0, -1);
            }

            // 1. EXPAND
            var expandedEquation = $tw.wiki.renderText(
                "text/plain",
                "text/vnd.tiddlywiki",
                rawEq,
                { parentWidget: this.parentWidget }
            );

            // 2. PREPARE FOR CALCULATION

            var calcString = expandedEquation
                .replace(/\^/g, "**")
                .replace(/\bsqrt\b/g, "Math.sqrt")
                .replace(/\bsin\b/g, "Math.sin")
                .replace(/\bcos\b/g, "Math.cos")
                .replace(/\btan\b/g, "Math.tan")
                .replace(/\blog\b/g, "Math.log10")
                .replace(/\bln\b/g, "Math.log")
                .replace(/\bpi\b/g, "Math.PI")
                .replace(/\be\b/g, "Math.E");

            // 3. SECURITY CHECK
            // Remove known safe math functions to check for unknown characters
            var checkString = calcString
                .replace(/Math\.(sqrt|sin|cos|tan|log10|log|PI|E)/g, "");

            if (/[^0-9+\-*/(). \t\r\n]/.test(checkString)) {
                return showKatex ? "$$ \\text{Error} $$" : "Error";
            }

            // 4. SOLVE
            var result = Function('"use strict";return (' + calcString + ')')();

            // --- IF PLAINTEXT MODE, RETURN NOW ---
            if (!showKatex) {
                if (!Number.isInteger(result) && isFinite(result)) {
                    return parseFloat(result.toFixed(4)).toString();
                }
                return result.toString();
            }

            // --- KATEX FORMATTING LOGIC ---

            // A. Format the Result
            var resultStr = result.toString();
            var formattedResult = resultStr;

            // Check for Infinity
            if (result === Infinity) {
                formattedResult = "\\infty";
            } else if (result === -Infinity) {
                formattedResult = "-\\infty";
            }
            // Check for repeating decimals / irrational
            else if (resultStr.length > 10 && resultStr.includes('.')) {
                if (/3{5,}5?$/.test(resultStr)) {
                    formattedResult = resultStr.replace(/3{5,}5?$/, "") + "\\overline{3}";
                }
                else if (/6{5,}7?$/.test(resultStr)) {
                    formattedResult = resultStr.replace(/6{5,}7?$/, "") + "\\overline{6}";
                }
                else {
                    formattedResult = parseFloat(result.toFixed(4)) + "...";
                }
            }

            // B. Format the Equation
            var displayString = expandedEquation;

            displayString = displayString
                .replace(/\bsqrt\(([^)]+)\)/g, "\\sqrt{$1}")
                .replace(/\bsin\b/g, "\\sin")
                .replace(/\bcos\b/g, "\\cos")
                .replace(/\btan\b/g, "\\tan")
                .replace(/\blog\b/g, "\\log")
                .replace(/\bln\b/g, "\\ln")
                .replace(/\bpi\b/g, "\\pi");

            // Find a top-level '/' (at parenthesis depth 0) for \frac formatting
            var splitIndex = -1;
            var depth = 0;
            for (var i = 0; i < displayString.length; i++) {
                if (displayString[i] === '(') depth++;
                else if (displayString[i] === ')') depth--;
                else if (displayString[i] === '/' && depth === 0) {
                    if (splitIndex !== -1) {
                        // Multiple top-level slashes â€” too complex for a single \frac
                        splitIndex = -2;
                        break;
                    }
                    splitIndex = i;
                }
            }

            if (splitIndex >= 0) {
                var numer = displayString.slice(0, splitIndex).trim();
                var denom = displayString.slice(splitIndex + 1).trim();
                displayString = "\\frac{" + numer + "}{" + denom + "}";
            } else {
                displayString = displayString.replace(/\//g, "\\div");
            }

            displayString = displayString
                .replace(/\*/g, "\\times")
                .replace(/\^/g, "^");

            return "$$ " + displayString + " = " + formattedResult + " $$";

        } catch (e) {
            console.log("Calc Macro Error:", e);
            return showKatex ? "$$ \\text{Calc Error} $$" : "Error";
        }
    };

})();"},"$:/lithic/macros/dynaview-startup.js":{"title":"$:/lithic/macros/dynaview-startup.js","type":"application/javascript","module-type":"macro","text":"/*\
title: $:/lithic/macros/dynaview-startup.js
type: application/javascript
module-type: macro

Macro to read Dynaview's saved scroll position tiddler from localStorage.
\*/
(function(){
"use strict";

exports.name = "dynaview-startup-tiddler";
exports.params = [];

exports.run = function() {
    if(typeof window !== "undefined") {
        try {
            // CACHE: Return the initial startup tiddler title if already calculated.
            // This prevents the macro's output from changing during scrolling,
            // which would cause `<$set>` to destroy and recreate the entire ViewTemplate!
            if (window.lithicDynaviewStartupTitle) {
                return window.lithicDynaviewStartupTitle;
            }

            var stateTiddler = "$:/config/dynaview/scroll";

            // ONE-TIME POLYFILL INJECTION
            if(!window.lithicDynaviewPolyfilled) {
                window.lithicDynaviewPolyfilled = true;

                var isWaitingForAnimationFrame = false;
                window.addEventListener("scroll", function() {
                    if(!isWaitingForAnimationFrame) {
                        window.requestAnimationFrame(function() {
                            if($tw.wiki.getTiddlerText("$:/config/DynaView/RestoreScrollPositionAtStartup", "").trim() === "yes") {
                                var elements = document.querySelectorAll(".tc-tiddler-frame[data-tiddler-title]"),
                                    topmostElement = null,
                                    topmostElementTop = 1000000;

                                $tw.utils.each(elements,function(element) {
                                    var rect = element.getBoundingClientRect();
                                    if((rect.top < topmostElementTop) && (rect.bottom > 0)) {
                                        topmostElement = element;
                                        topmostElementTop = rect.top;
                                    }
                                });

                                if(topmostElement) {
                                    var newJson = JSON.stringify({
                                        title: topmostElement.getAttribute("data-tiddler-title"),
                                        offset: -topmostElementTop
                                    });
                                    if($tw.wiki.getTiddlerText(stateTiddler) !== newJson) {
                                        $tw.wiki.addTiddler(new $tw.Tiddler({title: stateTiddler, text: newJson}));
                                    }
                                }
                            }
                            isWaitingForAnimationFrame = false;
                        });
                        isWaitingForAnimationFrame = true;
                    }
                }, false);
            }

            var data = $tw.wiki.getTiddlerText(stateTiddler);
            if(data) {
                var json = JSON.parse(data);
                if(json && json.title) {
                    // ONE-TIME RESTORE POLYFILL
                    if(!window.lithicDynaviewRestored) {
                        window.lithicDynaviewRestored = true;
                        window.lithicDynaviewStartupTitle = json.title;
                        setTimeout(function() {
                            var elements = document.querySelectorAll(".tc-tiddler-frame[data-tiddler-title]");
                            $tw.utils.each(elements,function(element) {
                                if(element.getAttribute("data-tiddler-title") === json.title) {
                                    var rect = element.getBoundingClientRect(),
                                        scrollY = Math.round(window.scrollY + rect.top + json.offset);
                                    if(Math.abs(scrollY - window.scrollY) > 5) {
                                        window.scrollTo(window.scrollX, scrollY);
                                    }
                                }
                            });
                        }, 500); // Wait for DOM to settle after Lithic store injection
                    }
                    return json.title;
                }
            }
        } catch(e) {
            console.error("dynaview-startup-tiddler error:", e);
        }
    }
    return "";
};
})();
"},"$:/lithic/macros/embed-stream":{"title":"$:/lithic/macros/embed-stream","tags":"$:/tags/Global","type":"text/vnd.tiddlywiki","text":"\procedure .stream-recurse(line-spacing:"1", hide-bullets:"no")
