title: $:/lithic/modules/action-highlight.js
type: application/javascript
module-type: widget

Action widget to highlight text in the story river ephemerally.

\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var HighlightWidget = function(parseTreeNode,options) {
	this.initialise(parseTreeNode,options);
};

HighlightWidget.prototype = new Widget();

HighlightWidget.prototype.render = function(parent,nextSibling) {
	this.computeAttributes();
	this.execute();
};

HighlightWidget.prototype.execute = function() {
	this.text = this.getAttribute("text","");
};

HighlightWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if(changedAttributes.text) {
		this.refreshSelf();
		return true;
	}
	return this.refreshChildren(changedTiddlers);
};

HighlightWidget.prototype.invokeAction = function(triggeringWidget,event) {
	if(!this.text) return true;

	var searchText = this.text.trim();
	if(!searchText || searchText.length < 2) return true; // ignore empty or 1-char

    var regex;
    try {
        regex = new RegExp("(" + searchText.replace(/[-[\]{}()*+?.,\\^$|#\s]/g, '\\$&') + ")", "gi");
    } catch(e) {
        return true;
    }

    var storyRiver = document.querySelector(".tc-story-river");
    if(!storyRiver) return true;

    // Function to walk DOM and highlight text nodes
    var highlightNode = function(element) {
        var walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null, false);
        var nodesToReplace = [];
        var node;
        while (node = walker.nextNode()) {
            if (node.parentNode && node.parentNode.nodeName !== 'SCRIPT' && node.parentNode.nodeName !== 'STYLE' && node.parentNode.nodeName !== 'MARK') {
                if (regex.test(node.nodeValue)) {
                    nodesToReplace.push(node);
                }
            }
        }

        nodesToReplace.forEach(function(n) {
            var span = document.createElement("span");
            span.className = "lithic-ephemeral-highlight-container";
            span.innerHTML = n.nodeValue.replace(regex, "<mark class='lithic-ephemeral-highlight' style='background-color: var(--lithic-c-code-select-bg); color: var(--lithic-c-code-select-fg); border-radius: 2px; padding: 0 2px;'>$1</mark>");
            if(n.parentNode) {
                n.parentNode.replaceChild(span, n);
            }
        });
    };

    // 1. Highlight anything currently in the story river (after a brief delay for TW render)
    setTimeout(function() {
        highlightNode(storyRiver);
    }, 100);

    // 2. Setup MutationObserver for Dynaview dynamic rendering
    var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
            mutation.addedNodes.forEach(function(node) {
                if(node.nodeType === 1) { // ELEMENT_NODE
                    highlightNode(node);
                }
            });
        });
    });

    observer.observe(storyRiver, { childList: true, subtree: true });

    // 3. Setup click listener to clear highlights
    var clearHighlight = function() {
        observer.disconnect();

        var containers = document.querySelectorAll("span.lithic-ephemeral-highlight-container");
        for(var i=0; i<containers.length; i++) {
            var container = containers[i];
            var parent = container.parentNode;
            if(!parent) continue;
            var frag = document.createDocumentFragment();
            while(container.firstChild) {
                var c = container.firstChild;
                if(c.nodeName === 'MARK') {
                    while(c.firstChild) {
                        frag.appendChild(c.firstChild);
                    }
                    container.removeChild(c);
                } else {
                    frag.appendChild(c);
                }
            }
            parent.replaceChild(frag, container);
            parent.normalize();
        }
        document.body.removeEventListener("click", clearHighlight, true);
    };

    // wait a tick before adding the listener so the current click doesn't instantly clear it
    setTimeout(function() {
        document.body.addEventListener("click", clearHighlight, true);
    }, 200);

	return true; // Action was invoked
};

exports["action-highlight"] = HighlightWidget;

})();
"},"$:/lithic/startup/idle-autosaver.js":{"title":"$:/lithic/startup/idle-autosaver.js","module-type":"startup","tags":"","type":"application/javascript","text":"/*\
title: $:/lithic/startup/idle-autosaver.js
type: application/javascript
module-type: startup

Idle-based Auto-Saver for Lithic TiddlyWiki
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

exports.name = "idle-autosaver";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
	if(typeof window === "undefined") {
		return;
	}

	// 1. Prevent the script from running entirely on standalone file:// wikis
	if (window.location.protocol === "file:") {
		return;
	}

	// 2. Short-circuit if AutoSave configuration is not explicitly set to "yes" at startup
	// Note: Changing this config setting requires reloading the wiki to take effect.
	var autoSaveConfig = $tw.wiki.getTiddlerText("$:/config/AutoSave", "no");
	if (autoSaveConfig !== "yes") {
		return;
	}

	var IDLE_TIMEOUT = 3000; // 3 seconds
	var saveTimer = null;

	function triggerSave() {
		// Respect the temporary disable state for new/injected wikis
		var disableAutoSave = $tw.wiki.getTiddlerText("$:/state/DisableAutoSaver");
		if (disableAutoSave === "yes") {
			return;
		}

		if ($tw.rootWidget) {
			// Trigger the core auto-save mechanism
			$tw.rootWidget.dispatchEvent({type: "tm-auto-save-wiki"});
		}
	}

	// Persistently hijack the notifier to swallow save notifications when auto-save is active
	if ($tw.notifier && typeof $tw.notifier.display === "function") {
		var originalNotifier = $tw.notifier.display;
		var wasLocked = $tw.wiki.getTiddlerText("$:/state/DisableAutoSaver") === "yes";
		var unlockedAt = 0;

		$tw.notifier.display = function(title, options) {
			var disableAutoSave = $tw.wiki.getTiddlerText("$:/state/DisableAutoSaver");

			// Track the transition from locked to unlocked
			if (disableAutoSave === "yes") {
				wasLocked = true;
			} else if (wasLocked) {
				wasLocked = false;
				unlockedAt = Date.now();
			}

			// If auto-save is fully active (no lock) AND we are past the 3-second grace period
			if (disableAutoSave !== "yes" && (Date.now() - unlockedAt > 3000)) {
				if (title === "$:/language/Notifications/Save/Done" || title === "$:/language/Notifications/Save/Starting") {
					return;
				}
			}
			// Pass through any other notifications (errors, etc) or all notifications if auto-save is locked/graced
			originalNotifier.apply($tw.notifier, arguments);
		};
	}

	function resetTimer() {
		if(saveTimer) {
			clearTimeout(saveTimer);
		}
		// Reset the 15 second countdown
		saveTimer = setTimeout(triggerSave, IDLE_TIMEOUT);
	}

	// Listen for typical interaction events to debounce
	window.addEventListener("keydown", resetTimer, {passive: true});
	window.addEventListener("mousedown", resetTimer, {passive: true});
	window.addEventListener("mousemove", resetTimer, {passive: true});
	window.addEventListener("touchstart", resetTimer, {passive: true});
	window.addEventListener("scroll", resetTimer, {passive: true});

	// Start the initial countdown
	resetTimer();
};

})();
"},"$:/lithic/startup/import-tracker.js":{"title":"$:/lithic/startup/import-tracker.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/lithic/startup/import-tracker.js
type: application/javascript
module-type: startup

Stamps imported tiddlers with an "imported" date field.
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

exports.name = "lithic-import-tracker";
exports.platforms = ["browser", "node"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
	$tw.hooks.addHook("th-importing-tiddler", function(tiddler) {
		return new $tw.Tiddler(tiddler, {modified: $tw.utils.stringifyDate(new Date())});
	});
};

})();
"},"$:/Lithic/startup/mobile-pwa-back-handler.js":{"title":"$:/Lithic/startup/mobile-pwa-back-handler.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/startup/mobile-pwa-back-handler.js
type: application/javascript
module-type: startup

Intercepts the Android PWA back swipe when the wiki is dirty, showing a confirm dialog instead of bypassing the beforeunload event.
\*/
(function(){
"use strict";

exports.name = "mobile-pwa-back-handler";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
    if(typeof window !== "undefined" && window.history && window.history.pushState) {

        // Ensure this only activates if we match PWA conditions or mobile conditions. 
        // We'll activate it generally for standalone/fullscreen, as mobile browsers will handle beforeunload anyway.
        var isPwa = window.matchMedia('(display-mode: standalone)').matches || 
                    window.matchMedia('(display-mode: fullscreen)').matches || 
                    window.navigator.standalone;

        var isAndroid = /Android/i.test(navigator.userAgent);

        if (isPwa && isAndroid) {
            var hasPushedState = false;

            // Check if wiki is dirty based on TW's own SaverFilter
            var checkDirty = function() {
                var filter = $tw.wiki.getTiddlerText("$:/config/SaverFilter", "[is[tiddler]] -[prefix[$:/info/]] -[prefix[$:/temp/]] -[prefix[$:/state/]] -[prefix[$:/status/]] -[prefix[$:/HistoryList]] -[prefix[$:/StoryList]] -[[favicon.ico]]");
                var dirtyTiddlers = $tw.wiki.filterTiddlers(filter);
                return dirtyTiddlers.length > 0;
            };

            var updateHistoryState = function() {
                var currentlyDirty = checkDirty();

                if (currentlyDirty && !hasPushedState) {
                    // Push a dummy state so the first back press triggers popstate instead of exit
                    history.pushState({lithic_dirty_lock: true}, "", location.href);
                    hasPushedState = true;
                } else if (!currentlyDirty && hasPushedState) {
                    // If the wiki becomes clean, we could technically pop the state, 
                    // but it's tricky if they've navigated. For now, leave the state and handle in popstate.
                    // Or we could try history.back() but that might disrupt normal navigation.
                }
            };

            // Listen to wiki changes to update our dummy history state
            $tw.wiki.addEventListener("change", function(changes) {
                updateHistoryState();
            });

            // Handle the back button (which pops the state)
            window.addEventListener("popstate", function(event) {
                // If popstate fires, it means the state was popped.
                // We assume our pushed state is gone. We reset the flag.
                // Note: event.state is the state we are navigating TO.
                hasPushedState = false;

                if (checkDirty()) {
                    var confirmMsg = $tw.language.getString("Notifications/Save/UnsavedChanges");
                    if (!confirmMsg) {
                        confirmMsg = "You have unsaved changes. Are you sure you want to leave?";
                    }
                    if (confirm(confirmMsg)) {
                        // User wants to leave, let them exit by going back again
                        window.history.back();
                    } else {
                        // User wants to stay, push the state again
                        history.pushState({lithic_dirty_lock: true}, "", location.href);
                        hasPushedState = true;
                    }
                } else {
                    // Not dirty, allow exit
                    window.history.back();
                }
            });

            // Initial check just in case it loads dirty
            updateHistoryState();

            // Prevent ESC key from acting as a "Back" button on Android tablets with physical keyboards.
            // We catch this at the window level (bubble phase) so any inputs/modals have already processed it,
            // but we stop the default OS behavior which exits the app.
            window.addEventListener("keydown", function(event) {
                if (event.key === "Escape" || event.keyCode === 27) {
                    event.preventDefault();
                }
            });
        }
    }
};

})();
"},"$:/lithic/startup/register-lith-extension.js":{"title":"$:/lithic/startup/register-lith-extension.js","module-type":"startup","tags":"","type":"application/javascript","text":"/*\
title: $:/lithic/startup/register-lith-extension.js
type: application/javascript
module-type: startup

Registers the .lith file extension to be handled by the core JSON deserializer.
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

// Export name and synchronous status
exports.name = "register-lith-extension";
exports.platforms = ["browser", "node"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
    // Map the custom extension to our custom .lith MIME type
    $tw.config.fileExtensionInfo[".lith"] = { type: "text/vnd.lithic" };
    // Register the content type so TW's import pipeline can resolve it
    $tw.config.contentTypeInfo["text/vnd.lithic"] = { encoding: "utf8", extension: ".lith" };
    // Register the deserializer directly into the boot-time collection
    // (avoids tiddlerdeserializer module-type which forces a reload cycle)
    if($tw.Wiki.tiddlerDeserializerModules) {
        $tw.Wiki.tiddlerDeserializerModules["text/vnd.lithic"] = function(text, fields) {
            var results = [];
            var chunks = text.split(/(?:\r?\n)*\u2042\u2042\u2042(?:\r?\n)*/);
            for(var i = 0; i < chunks.length; i++) {
                var chunk = chunks[i].trim();
                if(!chunk) continue;
                var blankLineMatch = /\r?\n\r?\n/.exec(chunk);
                var headerStr, bodyText;
                if(blankLineMatch) {
                    headerStr = chunk.substring(0, blankLineMatch.index);
                    bodyText = chunk.substring(blankLineMatch.index + blankLineMatch[0].length);
                } else {
                    headerStr = chunk;
                    bodyText = "";
                }
                var tiddlerFields = $tw.utils.parseFields(headerStr);
                if(tiddlerFields) {
                    if(bodyText) {
                        tiddlerFields.text = bodyText;
                    }
                    if(fields) {
                        for(var field in fields) {
                            if(tiddlerFields[field] === undefined) {
                                tiddlerFields[field] = fields[field];
                            }
                        }
                    }

                    if (tiddlerFields.title && !tiddlerFields.title.startsWith("$:/") && !tiddlerFields.type) {
                        tiddlerFields.type = "text/markdown";
                    }

                    results.push(tiddlerFields);
                }
            }
            return results;
        };
    }
};

})();"},"$:/lithic/startup/standalone-transient-recovery.js":{"title":"$:/lithic/startup/standalone-transient-recovery.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/lithic/startup/standalone-transient-recovery.js
type: application/javascript
module-type: startup

Slim transient recovery for standalone file:// Lithic HTML apps.

This intentionally does not use the official BrowserStorage plugin: that plugin
stores the whole wiki in localStorage. We keep only the latest changed user
tiddlers (or deletion tombstones) for the current local HTML file, and only
use them to offer a one-time downloaded recovery copy after a later launch.
\*/
(function(){
"use strict";

exports.name = "standalone-transient-recovery";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

var STORAGE_PREFIX = "lithic-standalone-dirty-v1:";
var RECOVERY_MODAL = "$:/lithic/ui/StandaloneTransientRecovery";
var PREVIEW_TITLE = "$:/temp/lithic/standalone-recovery-preview";
var SAVE_DONE_NOTIFICATION = "$:/language/Notifications/Save/Done";
var DEBOUNCE_MS = 1500;
var PREVIEW_EXCERPT_CHARS = 120;
var PREVIEW_MAX_TITLES = 3;

exports.startup = function(){
    if(typeof window === "undefined" || window.location.protocol !== "file:") {
        return;
    }

    var storageKey = STORAGE_PREFIX + encodeURIComponent(
        window.location.href.split("#")[0].split("?")[0]
    );
    var draft = {};
    var flushTimer = null;
    var activeRecord = null;
    var replayingRecovery = false;
    var filterText = $tw.wiki.getTiddlerText(
        "$:/config/SaverFilter",
        "[all[]] -[prefix[$:/state/]] -[prefix[$:/temp/]] -[prefix[$:/info/]] -[prefix[$:/HistoryList]] -[prefix[$:/StoryList]]"
    );
    var filterFn = null;
    try {
        filterFn = $tw.wiki.compileFilter(filterText);
    } catch(e) {
        // Fall back to the namespace check below if the configured filter is invalid.
    }

    function safeGet(){
        try {
            var raw = window.localStorage.getItem(storageKey);
            if(!raw) return null;
            var parsed = JSON.parse(raw);
            if(!parsed || parsed.v !== 1 || !Array.isArray(parsed.items) || parsed.items.length === 0) {
                return null;
            }
            return parsed;
        } catch(e) {
            return null;
        }
    }

    function safeClear(){
        try { window.localStorage.removeItem(storageKey); } catch(e) { /* best effort */ }
    }

    function cancelFlush(){
        if(flushTimer) {
            window.clearTimeout(flushTimer);
            flushTimer = null;
        }
    }

    function flush(){
        flushTimer = null;
        if(replayingRecovery) return;
        var titles = Object.keys(draft);
        if(titles.length === 0) return;
        var items = titles.map(function(title){ return draft[title]; });
        var record = {v: 1, ts: Date.now(), items: items};
        try {
            window.localStorage.setItem(storageKey, JSON.stringify(record));
        } catch(e) {
            // A single very large edited tiddler can still exceed browser
            // storage. Never interfere with the wiki itself if that happens.
            console.warn("Lithic transient recovery could not persist the draft:", e);
        }
    }

    function scheduleFlush(){
        if(replayingRecovery || flushTimer) return;
        flushTimer = window.setTimeout(flush, DEBOUNCE_MS);
    }

    function isTrackedTitle(title, tiddler){
        if(!title) return false;
        if(!tiddler) {
            // Filter functions cannot inspect a deleted tiddler, but normal
            // user titles are safe deletion tombstones; skip engine spaces.
            return title.indexOf("$:/") !== 0 && title !== "favicon.ico";
        }
        try {
            // Evaluate the configured save filter ONCE against this title and
            // check membership. The filter must decide, not raw prefixes:
            // Lithic's SaverFilter starts with [all[]], so a naive
            // iterator(tiddler,title) probe would match nearly anything.
            return filterFn
                ? filterFn.call($tw.wiki, $tw.wiki.makeTiddlerIterator([title])).indexOf(title) !== -1
                : title.indexOf("$:/") !== 0 && title !== "favicon.ico";
        } catch(e) {
            return title.indexOf("$:/") !== 0 && title !== "favicon.ico";
        }
    }

    function capture(changes){
        if(replayingRecovery || !changes) return;
        $tw.utils.each(changes, function(change, title){
            if(!change || (!change.modified && !change.deleted)) return;
            var tiddler = $tw.wiki.getTiddler(title);
            if(!isTrackedTitle(title, tiddler)) return;
            if(change.deleted || !tiddler) {
                draft[title] = {t: title, d: 1};
                return;
            }
            var fields = {title: title};
            $tw.utils.each(tiddler.fields, function(value, field){
                fields[field] = value;
            });
            draft[title] = {t: title, f: fields};
        });
        scheduleFlush();
    }

    function recordToDraft(record){
        var result = {};
        if(record && Array.isArray(record.items)) {
            $tw.utils.each(record.items, function(item){
                if(item && item.t) result[item.t] = item;
            });
        }
        return result;
    }

    function recoveredFilename(){
        var path = window.location.pathname || "";
        var name = path.substring(path.lastIndexOf("/") + 1);
        try { name = decodeURIComponent(name); } catch(e) { /* keep encoded name */ }
        if(!name || !/\.html?$/i.test(name)) name = "lithic.html";
        var stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
        return name.replace(/\.html?$/i, "_recovered_" + stamp + ".html");
    }

    function pickExcerpt(record){
        // Prefer the largest captured tiddler: it is the most likely to carry
        // recognizable content (the first entry may be a trivial one-word
        // edit). Ties keep the earliest entry so the choice is stable.
        var best = null;
        var bestLen = -1;
        for(var i = 0; i < record.items.length; i++) {
            var item = record.items[i];
            if(!item || item.d || !item.f || typeof item.f.text !== "string") continue;
            if(!item.f.text.replace(/\s+/g, "").length) continue;
            if(item.f.text.length > bestLen) {
                best = item.f.text;
                bestLen = item.f.text.length;
            }
        }
        return best || "";
    }

    // Build the small plaintext preview shown in the recovery modal: entry
    // count, affected titles (deletions marked), and a short raw excerpt of
    // the largest captured tiddler so the user can sanity-check the journal
    // before choosing Download or Discard.
    function buildRecoveryPreview(record){
        var items = record.items || [];
        var titles = [];
        var shown = 0;
        var hidden = 0;
        for(var i = 0; i < items.length; i++) {
            var item = items[i];
            if(!item || !item.t) continue;
            if(shown < PREVIEW_MAX_TITLES) {
                titles.push((item.d ? item.t + " (deleted)" : item.t));
                shown++;
            } else {
                hidden++;
            }
        }
        var lines = [items.length + (items.length === 1 ? " tiddler captured" : " tiddlers captured")];
        if(titles.length) lines.push(titles.join("\n"));
        if(hidden) lines.push("\u2026and " + hidden + " more");
        var excerpt = pickExcerpt(record);
        if(excerpt) {
            excerpt = excerpt.replace(/\r\n/g, "\n").slice(0, PREVIEW_EXCERPT_CHARS);
            lines.push("\u2014\u2014\u2014");
            lines.push(excerpt + (excerpt.length >= PREVIEW_EXCERPT_CHARS ? "\u2026" : ""));
        }
        return lines.join("\n");
    }

    function showRecoveryPreview(record){
        try {
            $tw.wiki.addTiddler(new $tw.Tiddler({
                title: PREVIEW_TITLE,
                text: buildRecoveryPreview(record)
            }));
        } catch(e) {
            // The preview is cosmetic; never let it block recovery itself.
        }
    }

    function clearRecoveryPreview(){
        try { $tw.wiki.deleteTiddler(PREVIEW_TITLE); } catch(e) { /* best effort */ }
    }

    function closeRecoveryModal(widget){
        if(widget && widget.dispatchEvent) {
            widget.dispatchEvent({type: "tm-close-tiddler"});
        }
    }

    function removeRecoveryHandlers(){
        // Handlers are one-shot by design: the prompt must not be re-usable
        // after a decision, so stale modal widgets can never re-trigger a
        // replay or a second discard of an already-cleared journal.
        if(!$tw.rootWidget.__lithicTransientRecoveryDownload) return;
        $tw.rootWidget.removeEventListener("tm-lithic-standalone-download-recovery",$tw.rootWidget.__lithicTransientRecoveryDownload);
        $tw.rootWidget.removeEventListener("tm-lithic-standalone-discard-recovery",$tw.rootWidget.__lithicTransientRecoveryDiscard);
        $tw.rootWidget.__lithicTransientRecoveryDownload = null;
        $tw.rootWidget.__lithicTransientRecoveryDiscard = null;
    }

    function downloadRecovery(widget){
        var record = activeRecord || safeGet();
        if(!record) return;
        replayingRecovery = true;
        cancelFlush();
        try {
            for(var i = 0; i < record.items.length; i++) {
                var item = record.items[i];
                if(!item || !item.t) continue;
                if(item.d) {
                    $tw.wiki.deleteTiddler(item.t);
                } else if(item.f) {
                    $tw.wiki.addTiddler(new $tw.Tiddler($tw.utils.extend(
                        {title: item.t},
                        item.f
                    )));
                }
            }
        } finally {
            replayingRecovery = false;
        }
        // Merge, don't clobber: any edits made in this session before the user
        // clicked Download must survive alongside the replayed journal.
        for(var key in draft) {
            if($tw.utils.hop(draft, key)) record.items.push(draft[key]);
        }
        draft = recordToDraft(record);
        safeClear();
        clearRecoveryPreview();
        // Keep the recovered state journaled (in draft, flushed on next edit
        // or unload) until the normal saver confirms the new complete HTML
        // copy was accepted for download.
        activeRecord = null;
        removeRecoveryHandlers();
        closeRecoveryModal(widget);
        window.setTimeout(function(){
            $tw.rootWidget.dispatchEvent({
                type: "tm-save-wiki",
                param: "$:/core/save/all",
                paramObject: {filename: recoveredFilename()}
            });
        }, 0);
    }

    function discardRecovery(widget){
        cancelFlush();
        safeClear();
        clearRecoveryPreview();
        activeRecord = null;
        draft = {};
        removeRecoveryHandlers();
        closeRecoveryModal(widget);
    }

    $tw.wiki.addEventListener("change", capture);

    // A successful ordinary standalone save means the transient journal is no
    // longer needed. SaverHandler emits this notification after the saver has
    // accepted the serialized HTML for download.
    if($tw.notifier && typeof $tw.notifier.display === "function" && !$tw.notifier.__lithicTransientRecoveryHooked) {
        var originalDisplay = $tw.notifier.display;
        $tw.notifier.display = function(title){
            if(title === SAVE_DONE_NOTIFICATION) {
                cancelFlush();
                safeClear();
                draft = {};
                activeRecord = null;
            }
            return originalDisplay.apply($tw.notifier, arguments);
        };
        $tw.notifier.__lithicTransientRecoveryHooked = true;
    }

    window.addEventListener("pagehide", flush);
    window.addEventListener("beforeunload", flush);

    activeRecord = safeGet();
    if(activeRecord) {
        window.setTimeout(function(){
            if($tw.modal && $tw.wiki.getTiddler(RECOVERY_MODAL)) {
                showRecoveryPreview(activeRecord);
                $tw.modal.display(RECOVERY_MODAL, {
                    variables: {
                        recoveryCount: String(activeRecord.items.length),
                        recoveryTime: new Date(activeRecord.ts).toLocaleString()
                    }
                });
            }
        }, 0);
    }

    // Message handlers are installed on the root widget so the modal tiddler
    // stays a normal exportable tiddler and the behavior remains local to this
    // startup module. Both handlers are one-shot: removeRecoveryHandlers()
    // unbinds them after the first decision. The guard flag only prevents
    // double-installation within a single boot (e.g. double startup invoke).
    if(!$tw.rootWidget.__lithicTransientRecoveryHandlers) {
        $tw.rootWidget.__lithicTransientRecoveryHandlers = true;
        $tw.rootWidget.__lithicTransientRecoveryDownload = function(event){
            downloadRecovery(event.widget);
            return false;
        };
        $tw.rootWidget.__lithicTransientRecoveryDiscard = function(event){
            discardRecovery(event.widget);
            return false;
        };
        $tw.rootWidget.addEventListener("tm-lithic-standalone-download-recovery",$tw.rootWidget.__lithicTransientRecoveryDownload);
        $tw.rootWidget.addEventListener("tm-lithic-standalone-discard-recovery",$tw.rootWidget.__lithicTransientRecoveryDiscard);
    }
};

})();"},"$:/lithic/styles/AdvancedSearch.css":{"title":"$:/lithic/styles/AdvancedSearch.css","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":".lithic-sidebar-search .tc-advanced-search input[type="search"] {
    display: block;
    width: 100%;
    margin-bottom: 5px;
}

.lithic-sidebar-search .tc-search-results a {
    display: block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.lithic-flex-input {
    flex: 1 1 0;
    min-width: 0;
    width: 100%;
}

.lithic-core-search-results .tc-advanced-search-filter-buttons {
    display: none !important;
}

.lithic-core-search-results .tc-advanced-search {
    display: none !important;
}

.lithic-sidebar-search .tc-advanced-search-filter-buttons button svg {
    width: 1.2em;
    height: 1.2em;
    fill: <<colour muted-foreground>>;
}

.lithic-sidebar-search .tc-advanced-search-filter-buttons button.tc-btn-invisible svg {
    width: 1.2em;
    height: 1.2em;
    fill: <<colour muted-foreground>>;
}"},"$:/lithic/styles/backlink-cloud-collapser.css":{"title":"$:/lithic/styles/backlink-cloud-collapser.css","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":"/* ── Backlink Cloud Collapser ── */

/* Hide wrapper entirely when the footer has no backlink pills */
.backlink-cloud-wrapper:not(:has(.footer li)) {
  display: none;
}

/* Container: one row, so the toggle keeps a lane of its own instead of
   floating over the pills. The lane is pulled out by the width the streams
   add-node control sits at (4px column padding + 16px arrow), which is the
   button this toggle lines up under. Pulling it out here rather than
   overhanging the button keeps the row inside the tiddler frame. */
.backlink-cloud-wrapper {
  display: flex;
  align-items: flex-start;
  gap: 2px;
  margin-left: -20px;
  padding-left: 20px;
}

/* Streams only outdents its control column by 1em below 600px, so the gap
   the lane fills is already closed there. */
@media (max-width: 600px) {
  .backlink-cloud-wrapper {
    margin-left: 0;
    padding-left: 0;
  }
}

/* Pills take the rest of the row and wrap inside it, never under the toggle */
.backlink-cloud-wrapper > .footer {
  flex: 1 1 auto;
  min-width: 0;
}

/* The collapse toggle: a fixed 20px lane at the start of the row */
.backlink-cloud-collapser {
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  margin-top: 2px;
  padding: 0;
  border: none;
  background: none;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.backlink-cloud-collapser svg {
  fill: <<colour muted-foreground>>;
  transform: rotate(90deg);
  transition: transform 0.2s ease;
}

.backlink-cloud-collapsed .backlink-cloud-collapser svg {
  transform: rotate(0deg);
}

/* Always legible when the cloud IS collapsed (to indicate hidden content) */
.backlink-cloud-collapsed .backlink-cloud-collapser {
  opacity: 0.7;
}

/* Brighten on hover of the toggle or the row it sits in */
.backlink-cloud-wrapper:hover .backlink-cloud-collapser,
.backlink-cloud-collapser:hover {
  opacity: 1;
}

/* Hide the pill list when collapsed (CSS-based, keeps elements in DOM for :has check) */
.backlink-cloud-collapsed .footer {
  display: none;
}"},"$:/lithic/styles/center_notifications.css":{"title":"$:/lithic/styles/center_notifications.css","tags":"$:/tags/Stylesheet","text":"/* Center the TiddlyWiki notifications at the top of the window */
/* TW's core notifier toggles .tc-notification-highlight to trigger fade in/out */
.tc-notification {
    right: 0 !important;
    left: 0 !important;
    margin: 0 auto !important;
    width: max-content !important;
    max-width: 60vw !important;
    opacity: 0;
    transition: opacity 0.6s ease-in-out;
}

.tc-notification.tc-notification-highlight {
    opacity: 1;
}"},"$:/lithic/styles/headers.css":{"title":"$:/lithic/styles/headers.css","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* === Global Header Defaults (H1-H6) === 
   Targeting div.markdown to catch Streams nodes 
*/
.markdown h1, 
.markdown h2, 
.markdown h3, 
.markdown h4, 
.markdown h5, 
.markdown h6 {
  text-align: center;
  margin-top: .75em;
  margin-bottom: 0.5em;
  line-height: 1.2;
  border-bottom: none;
}

/* === H1: Main Title (Bold & Small Caps) === */
.markdown h1 {
  font-size: 3em;
  margin-top: 1.2em;
  font-weight: 700;
  font-variant: small-caps;
  text-transform: none;
}

/* === H2: Section Header (Floating Underline) === */
.markdown h2 {
  font-size: 2em;
  position: relative;
}

.markdown h2::after {
  content: '';
  display: block;
  width: 100px;
  border-bottom: 1px solid; 
  margin: 10px auto 0;
  opacity: 0.7;
}

/* === H3: Italic Sub-section === */
.markdown h3 {
  font-size: 1.5em;
  font-style: italic;
}

/* === H4: Left-aligned, Bold, Underlined === */
.markdown h4 {
  text-align: left;
  font-size: 1.2em;
  font-weight: 600;
  text-indent: 0.75em;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

/* === H5: Indented, Light, Underlined === */
.markdown h5 {
  text-align: left;
  font-size: 1.1em;
  font-weight: 400;
  text-indent: 1.5em;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

/* === H6: Image Caption Style === */
.markdown h6 {
  font-weight: 400;
  font-size: .8em;
  position: relative;
  top: -2.2em; 
  margin-bottom: 0;
  padding: 0;
  text-align: center;
  opacity: 0.8; 
  font-variant: small-caps;
  text-transform: none;
}

.markdown h6::before {
  content: '';
  display: block;
  width: 75%;
  height: 6px;
  border-bottom: 1px solid currentColor;
  border-left: 1px solid currentColor;
  border-right: 1px solid currentColor;
  margin: 0 auto 6px auto;
  opacity: 0.4;
}

.markdown h6::after {
  display: none;
}

/* === UI Helper: Header Underlay (Internal Method) === */
@media screen {
  /* We target the .markdown div directly if it contains a header.
     This avoids touching the .stream-row container which handles the 
     right-click context menu logic.
  */
  .markdown:has(:is(h1, h2)) {
    position: relative;
    /* Extra padding ensures the underlay doesn't look cramped against the text */
    padding: 4px 8px;
    /* Rounded corners on the markdown container background */
    border-radius: 8px;
    /* Subtle background tint */
    background-color: color-mix(in srgb, currentColor 6%, transparent);
  }
}

/* === Mobile Layout for Tiddler Titles === */
@media (max-width: 960px) {
  .tc-titlebar {
    display: flex;
    flex-direction: column;
  }
  .tc-titlebar .tc-tiddler-controls {
    /* Maintain controls on the right */
    align-self: flex-end;
    /* Optional: add slight spacing below the controls */
    margin-bottom: 8px;
  }
  .tc-titlebar .tc-title {
    /* Ensure title takes full width below controls */
    align-self: flex-start;
    margin-top: 0;
  }
}"},"$:/lithic/styles/printstyle.css":{"title":"$:/lithic/styles/printstyle.css","tags":"$:/tags/Stylesheet","type":"text/css","text":"@media print {
    /* =======================================================
       1. HIDE ALL NAVIGATION AND INTERFACE ELEMENTS
       (Ensures only content is printed)
       ======================================================= */

    /* Hide breadcrumbs */
    .sq-breadcrumbs-fragment {
        display: none !important;
    }

    /* Hide the entire custom top bar */
    .nc-topbar {
        display: none !important;
    }

    /* Hide the entire custom bottom bar */
    .nc-bottombar {
        display: none !important;
    }

    /* Hide the custom left sidebar and its resizer */
    .nc-sidebar,
    .oresizer {
        display: none !important;
    }

    /* The main TiddlyWiki Sidebar and its header */
    .tc-sidebar-scrollable,
    .tc-sidebar-header {
        display: none !important;
    }

    /* HIDE THE TIDDLER TITLE BAR (including title and controls) */
    .tc-titlebar {
        display: none !important;
    }

    /* The main 'ViewToolbar' buttons (e.g., Edit, Delete, Tag, permalink) */
    .tc-tiddler-controls,
    .tc-toolbar-group,
    .tc-toolbar-item {
        display: none !important;
    }

    /* HIDE THE TIDDLER FOOTER (e.g., backlinks, filter results) */
    .footer {
        display: none !important;
    }

    /* TiddlyWiki's core style for the Edit Template buttons/footer */
    .tc-editor-footer {
        display: none !important;
    }

    /* The Control Panel button (top right) */
    .tc-more-toolbar-wrapper {
        display: none !important;
    }

    /* If you have a custom Tiddler that shows the edit state */
    .tc-edit-text-wrapper {
        display: none !important;
    }

    /* Hide the 'Add New Node' button/control from Streams plugin */
    .stream-node-control-addnew {
        display: none !important;
    }

    /* Hide the Tiddler Subtitle (Date/Time info) */
    .tc-subtitle {
        display: none !important;
    }

    /* Hide the Tiddler Tags wrapper */
    .tc-tags-wrapper {
        display: none !important;
    }

    /* Hide the 'Copy to Clipboard' button on code blocks */
    svg.tc-image-copy-clipboard {
        display: none !important;
    }

    /* Hide transient UI notifications like "Saved Wiki" */
    .tc-notification {
        display: none !important;
    }

    /* =======================================================
       2. OPTIMIZE CONTENT DISPLAY & FRAME FIXES
       (Ensures text takes up full page width and removes outlines)
       ======================================================= */

    /* Ensure the main content takes up the full width and strips shadows/borders */
    .tc-tiddler-frame {
        width: 100% !important;
        margin-left: 0 !important;
        padding: 0 !important;
        border: none !important;
        box-shadow: none !important; /* <-- This kills the shadow box at low zoom */
        background: transparent !important;
        /* Set page break to keep tiddlers from splitting awkwardly */
        page-break-inside: avoid;
    }

    /* Ensure the Story River expands to full width */
    .tc-story-river {
        width: 100% !important;
    }

    /* =======================================================
       3. GENERAL STREAM MODIFICATIONS
       ======================================================= */

    /* Remove the left indentation border from ALL stream children and ensure they are expanded */
    .stream-row-children {
        border-left: none !important;
        display: block !important;
    }

    /* =======================================================
       4. TYPOGRAPHY & COLORS
       (Overrides dark mode text for printing)
       ======================================================= */

    /* Force body text to pure black for better print contrast */
    body.tc-body {
        color: #000000 !important;
    }

    /* =======================================================
       5. CODEBLOCK BORDER FIX
       (Left-only barber-pole border for code blocks in print)
       ======================================================= */

    /* Left-only border with diagonal barber-pole stripe pattern */
    pre.hljs,
    pre {
        border: none !important;
        border-left: 6px solid #000 !important;
        border-image: repeating-linear-gradient(
            -45deg,
            #999999 0px,
            #999999 3.5px,
            #ffffff 4px,
            #ffffff 7.5px,
            #999999 8px
        ) 6 !important;
        border-image-width: 0 0 0 6px !important;
        padding: 10px !important;
        padding-left: 14px !important;
        background-color: #fcfcfc !important;
    }

    /* Strip the redundant border and padding from the inner code element */
    pre code.hljs,
    pre code {
        border: none !important;
        padding: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
    }

    /* =======================================================
       6. INTERNAL LINK FORMATTING
       (Forces internal TiddlyWiki links to black text)
       ======================================================= */

    a.tc-tiddlylink:not(.tc-tiddlylink-external) {
        color: #000000 !important;
        text-decoration: none !important;
    }

    /* =======================================================
       7. DOUBLE HR AS PAGE BREAK
       (Turns double <hr> into a hard page break; hides the visible bars)
       ======================================================= */

    hr:has(+ hr) {
        display: none !important;
    }

    hr + hr {
        border: none !important;
        margin: 0 !important;
        height: 0 !important;
        page-break-after: always !important;
        break-after: page !important;
    }

    /* =======================================================
       8. HIDE WHITEBOARD UI ELEMENTS
       (Ensures whiteboard content prints without menus)
       ======================================================= */

    /* Hide TLDraw Left Menu Panel and Icon */
    #TD-MenuPanel,
    #TD-MenuIcon,
    #TD-Page {
        display: none !important;
    }

    /* Hide TLDraw right-side UI (Zoom, Read Only indicator) */
    .c-bUEyht-jvfJsl-side-right,
    #TD-Zoom {
        display: none !important;
    }

    /* Hide TLDraw helper buttons (e.g. Center/Focus) */
    .c-chTrj {
        display: none !important;
    }

    /* Hide the dashed/dotted 'locked' outline around locked whiteboard shapes.
       tldraw renders locked shapes with a persistent indicator overlay
       (div.tl-indicator.tl-locked) whose SVG stroke is dashed via
       .tl-locked { stroke-dasharray: ... }, and a selected locked shape also
       gets a dashed selection box (.tl-bounds-center.tl-dashed). */
    .tl-indicator.tl-locked,
    .tl-locked,
    .tl-bounds-center.tl-dashed {
        display: none !important;
    }

    /* =======================================================
       9. CENTER IMAGES
       (Centers images and image containers instead of left-aligning)
       ======================================================= */

    /* Make all images block-level and auto-margin centered.
       display:block + margin:auto centers a block element within its
       parent regardless of the parent's text-align. */
    .tc-tiddler-body img,
    .markdown img {
        display: block !important;
        margin-left: auto !important;
        margin-right: auto !important;
    }

    /* Center only dedicated image wrapper elements, not all paragraphs */
    .tc-tiddler-body .tc-image-wrapper,
    .tc-tiddler-body [class*="image-container"] {
        text-align: center !important;
    }

    /* =======================================================
       10. AUTOTABLE HIDE CONTROLS
       (Hides the drag handle column and the 'Add Row' final row)
       ======================================================= */

    table:has(.lithic-row-droppable) th:last-child,
    table:has(.lithic-row-droppable) td:last-child,
    table:has(.lithic-row-droppable) tbody tr:last-child {
        display: none !important;
    }

    /* =======================================================
       11. PRINT SCALING
       ======================================================= */

    /* Bake in 75% zoom scaling for Chrome */
    html {
        zoom: 75% !important;
    }

    /* Leverage browser's native margin boxes for page numbering */
    @page {
        margin-bottom: 2.2cm; /* Moved up */
        margin-right: 2.2cm;  /* Moved left */
        @bottom-right {
            content: counter(page);
        }
    }

    /* =======================================================
       12. INLINE CODE FORMATTING
       (Angled dashed underline for printed inline code)
       ======================================================= */

    code:not(pre code) {
        color: #464646ff !important;
        background: transparent !important;
        border: none !important;
        border-radius: 0 !important;
        padding: 0 2px 3px 2px !important;

        /* Force background to print for the underline trick */
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
        -webkit-box-decoration-break: clone !important;
        box-decoration-break: clone !important;

        /* Angled dashed underline mimicking the barber pole */
        background-image: repeating-linear-gradient(
            -45deg,
            #000 0px,
            #000 1.5px,
            transparent 1.5px,
            transparent 4px
        ) !important;
        background-position: center bottom !important;
        background-size: calc(100% - 6px) 2px !important;
        background-repeat: no-repeat !important;

    }

    /* =======================================================
       13. MERMAID DIAGRAMS & SVGS
       (Preserve colors when printing)
       ======================================================= */
    svg,
    .mermaid,
    .mermaid .label,
    .mermaid .nodeLabel,
    .mermaid .edgeLabel {
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
}"},"$:/lithic/styles/sidebar-commands-toggle":{"title":"$:/lithic/styles/sidebar-commands-toggle","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":"

.lithic-commands-toggle-btn {
    position: absolute;
    right: 15px;
    top: 25px; /* Adjust according to header size */
    z-index: 100;
    cursor: pointer;
    background: none;
    border: none;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.lithic-nut-slider {
    width: 36px;
    height: 18px;
    background-color: <<colour foreground>>; /* Dark track */
    clip-path: polygon(6px 0%, calc(100% - 6px) 0%, 100% 50%, calc(100% - 6px) 100%, 6px 100%, 0% 50%);
    position: relative;
    display: flex;
    align-items: center;
    transition: background-color 0.2s;
    box-sizing: border-box;
}

.lithic-nut-slider.active {
    background-color: <<colour dropzone-background>>; /* Lithic orange/accent color */
}

.lithic-nut {
    width: 16px;
    height: 14px;
    background-color: <<colour background>>;
    clip-path: polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%);
    display: flex;
    justify-content: center;
    align-items: center;
    position: absolute;
    left: 4px;
    transition: left 0.2s, transform 0.2s;
}

.lithic-nut-hole {
    display: block;
    width: 6px;
    height: 6px;
    flex-shrink: 0;
    border-radius: 50%;
    background-color: <<colour foreground>>; /* Dark hole matching track */
    transition: background-color 0.2s;
}

.lithic-nut-slider.active .lithic-nut {
    left: 16px;
}

.lithic-nut-slider.active .lithic-nut-hole {
    background-color: <<colour dropzone-background>>; /* Matches the active orange track */
}

.lithic-inline-edit {
    background: <<colour tiddler-editor-background>>;
    border: 1px solid <<colour dropzone-background>>;
    color: inherit;
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
    width: calc(100% - 50px);
    border-radius: 4px;
    padding: 2px 4px;
    box-sizing: border-box;
}

.lithic-settings-heading {
    font-weight: 700;
    opacity: 0.6;
    padding: 4px 6px;
    margin-top: 0.5em;
}

.lithic-settings-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 4px 6px;
    cursor: pointer;
    gap: 8px;
    box-sizing: border-box;
}

.lithic-settings-label {
    flex: 1;
    text-align: left;
}

.lithic-settings-hint {
    font-size: 0.75em;
    font-style: italic;
    opacity: 0.55;
    white-space: nowrap;
}

.lithic-settings-link {
    padding: 2px 6px 4px;
}

.lithic-settings-link-btn {
    font-size: 0.85em;
    opacity: 0.75;
    color: <<colour tiddler-link-foreground>>;
    padding: 0;
    cursor: pointer;
}

.lithic-settings-link-btn:hover {
    opacity: 1;
    text-decoration: underline;
}
"},"$:/lithic/styles/sticky-pill-bar.css":{"title":"$:/lithic/styles/sticky-pill-bar.css","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* ── Sticky pill bar (mobile) ── */

/* Nothing to hold: no backlink pills and no prev/next pills */
.lithic-pill-bar:not(:has(.footer li)) {
  display: none;
}

/* The band is marked sticky by the tiddler that draws it, so the Lithic
   Settings toggle is settled at render time rather than here. */
@media (max-width: 960px) {
  .lithic-pill-bar-sticky {
    position: sticky;
    /* Clears the notebook theme's fixed bottom bar, which is the 52px
       topbar-height metric with its padding inside that box. */
    bottom: 52px;
    z-index: 10;
    /* Matches the frame it scrolls over, so only the seam marks the band. */
    background: var(--lithic-c-surface);
    border-top: 1px solid var(--lithic-c-line-alpha-12);
    padding: 6px 0;
  }
}"},"$:/lithic/ui/Favorites/ItemTemplate":{"title":"$:/lithic/ui/Favorites/ItemTemplate","text":"<$draggable tiddler=<<currentTiddler>>>
