  activeClass={{{ [<isActive>match[yes]then[lithic-favorite-active]else[]] }}}
>
  <$let tweakClass={{{ [[$:/state/lithic/tweak-sidebar]get[text]match[yes]then[lithic-favorite-item-tweak]else[]] }}}>
