"},"$:/plugins/byper/advanced-search/styles/fake-search":{"title":"$:/plugins/byper/advanced-search/styles/fake-search","tags":"$:/tags/Stylesheet","type":"text/vnd.tiddlywiki","text":"\rules only filteredtranscludeinline transcludeinline macrodef macrocallinline html

/* Fake Search Input to bridge advanced-search workflow */
button.tc-btn-invisible.nc-fake-search-button {
    width: 100%;
    text-align: left;
    padding: 0.4em 1em !important;
    border: 1px solid <<colour tiddler-editor-border>> !important;
    border-radius: 4px !important;
    background: <<colour tiddler-editor-background>> !important;
    color: <<colour muted-foreground>> !important;
    font-size: 0.9em;
    transition: all 0.2s ease-in-out;
    cursor: pointer;
    display: inline-block;
}

button.tc-btn-invisible.nc-fake-search-button:hover {
    border-color: <<colour primary>> !important;
    color: <<colour primary>> !important;
}

.nc-topbar .nc-fake-search-wrapper {
    display: inline-block;
    width: 200px;
    margin-left: 10px;
}

.nc-sidebar .nc-fake-search-wrapper {
    display: block;
    margin: 10px 0;
}

/* Modal Animations */
@keyframes advancedSearchOverlayFadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes advancedSearchModalPopIn {
    from { opacity: 0; transform: scale(0.97); }
    to { opacity: 1; transform: scale(1); }
}

.advanced-search-overlay {
    animation: advancedSearchOverlayFadeIn 0.15s ease-out;
}

.advanced-search-modal {
    animation: advancedSearchModalPopIn 0.15s ease-out forwards;
}

/* Mobile adjustments for advanced search modal */
@media (max-width: 768px) {
    .advanced-search-overlay {
        align-items: flex-start !important;
        padding-top: 5vh !important;
    }
    .advanced-search-modal {
        margin-top: 0 !important;
    }
}
"},"$:/plugins/kebi/tiddlystudy-references/filters":{"title":"$:/plugins/kebi/tiddlystudy-references/filters","tags":"$:/tags/ViewTemplate $:/tags/Macro","text":"\whitespace trim


\define generate-list(statetiddler, filter, class)
\whitespace trim
  <$reveal type="match" state="$statetiddler$" text="enable">
    <$list filter="$filter$ -[is[blank]]">
      <li class="$class$">
        <$link to={{!!title}}>
          <$let regex=":[0-9][0-9][.][0-9][0-9][0-9]$">
            <$text text={{{ [{!!title}search-replace:g:regexp<regex>,[]] }}}/>
          </$let>
        </$link>
      </li>
    </$list>
  </$reveal>
\end

<div class={{{ lithic-pill-bar [{$:/config/lithic/sticky-pill-bar}else[yes]match[no]then[]else[lithic-pill-bar-sticky]] +[join[ ]] }}}>
<$let
  backlink-cloud-state={{{ [[$:/state/lithic/backlink-cloud-visibility/]addsuffix<currentTiddler>] }}}
  backlink-cloud-default={{{ [{$:/config/lithic/backlink-cloud-default}else[show]] }}}
>
<div class={{{ backlink-cloud-wrapper [<backlink-cloud-state>get[text]else<backlink-cloud-default>match[hide]then[backlink-cloud-collapsed]] +[join[ ]] }}}>
  <$button class="tc-btn-invisible backlink-cloud-collapser">
    <$list filter="[<backlink-cloud-state>get[text]else<backlink-cloud-default>match[show]]" variable="ignore">
      <$action-setfield $tiddler=<<backlink-cloud-state>> text="hide"/>
    </$list>
    <$list filter="[<backlink-cloud-state>get[text]else<backlink-cloud-default>!match[show]]" variable="ignore">
      <$action-setfield $tiddler=<<backlink-cloud-state>> text="show"/>
    </$list>
    <svg width="20" height="20" viewBox="0 0 20 20"><path d="M13.75 9.56879C14.0833 9.76124 14.0833 10.2424 13.75 10.4348L8.5 13.4659C8.16667 13.6584 7.75 13.4178 7.75 13.0329L7.75 6.97072C7.75 6.58582 8.16667 6.34525 8.5 6.5377L13.75 9.56879Z"></path></svg>
  </$button>
  <ul class="footer">
  <$vars 
    targetTitle=<<currentTiddler>>
    safeAlias={{{ [enlist{!!aliases}first[]] ~[[$:/no-match-placeholder]] }}} 
    targets={{{ [<currentTiddler>] [enlist{!!aliases}first[]] +[format:titlelist[]join[ ]] }}}
  >
  <$let 
    lbrack="[[" rbrack="]]" pipe="|"
    hardLinks={{{ [enlist<targets>addprefix<lbrack>addsuffix<rbrack>] [enlist<targets>addprefix<pipe>addsuffix<rbrack>] +[format:titlelist[]join[ ]] }}}
    textBacklinks={{{ [enlist<hardLinks>] :map[all[tiddlers]!is[system]!is[image]!type[application/tldr]search:text:literal<currentTiddler>] +[format:titlelist[]join[ ]] }}}
    allBacklinks={{{ [enlist<targets>backlinks[]] [enlist<textBacklinks>] +[format:titlelist[]join[ ]] }}}
  >
  <<generate-list statetiddler:"$:/plugins/kebi/tiddlystudy-references/config/filters/transclusions" filter:"[enlist<targets>backtranscludes[]] -[is[current]] -[is[system]] -[all[shadows]] -[is[image]]" class:"filtertransclude">>
  <<generate-list statetiddler:"$:/plugins/kebi/tiddlystudy-references/config/filters/tags" filter:"[enlist<targets>tagging[]] -[enlist<targets>backtranscludes[]] -[is[current]] -[is[system]] -[all[shadows]]" class:"filtertag">>
  <<generate-list statetiddler:"$:/plugins/kebi/tiddlystudy-references/config/filters/backlinks" filter:"[enlist<allBacklinks>] -[enlist<targets>backtranscludes[]] -[enlist<targets>tagging[]] -[is[current]] -[is[system]] -[all[shadows]] -[is[image]] -[all[current]get[stream-list]enlist-input[]] +[unique[]]" class:"filterbacklink">>
  <<generate-list statetiddler:"$:/plugins/kebi/tiddlystudy-references/config/filters/mentions-title" filter:"[all[tiddlers]!is[system]!is[image]!type[application/tldr]search:title:literal<targetTitle>] [all[tiddlers]!is[system]!is[image]!type[application/tldr]search:title:literal<safeAlias>] +[unique[]] -[enlist<allBacklinks>] -[enlist<targets>backtranscludes[]] -[enlist<targets>tagging[]] -[has[parent]] -[is[current]] -[all[shadows]] -[all[current]get[stream-list]enlist-input[]]" class:"filtertitle">>
  </$let>
  </$vars>
  </ul>
</div>
</$let>

<$wikify name="primaryColor" text="<<colour primary>>">
<$let pillStyle={{{ [[background-color:transparent; border:1px solid ]] [<primaryColor>] [[;]] +[join[]] }}}>
<$let 
  streamList={{{ [<currentTiddler>get[parent]get[stream-list]] }}}
  prevTarget={{{ [<currentTiddler>get[prev]] ~[enlist<streamList>before<currentTiddler>] }}}
  nextTarget={{{ [<currentTiddler>get[next]] ~[enlist<streamList>after<currentTiddler>] }}}
>
