 $:/core/ui/Buttons/permaview $:/core/ui/Buttons/fold-others $:/core/ui/Buttons/fold-bar"},"$:/themes/nico/notebook/ui/Buttons/SwitchPalette":{"title":"$:/themes/nico/notebook/ui/Buttons/SwitchPalette","tags":"$:/tags/PageControls","type":"text/vnd.tiddlywiki","text":"<span class="desktop-only">
  <$vars
    palettes="[all[tiddlers+shadows]tag[$:/tags/notebook/Palette]]"
    popupTiddler=<<qualify "$:/state/notebook/palette-dropdown">>
  >
    <$button
      popup=<<popupTiddler>>
      tooltip="Switch colours"
      aria-label="Switch colours"
      class=<<tv-config-toolbar-class>>
    >
      <$list filter="[<tv-config-toolbar-icons>match[yes]]">
	{{$:/themes/nico/notebook/images/color-switch}}
      </$list>

      <$list filter="[<tv-config-toolbar-text>match[yes]]">
	<span class="tc-btn-text">Switch colours</span>
      </$list>

      <$reveal state=<<popupTiddler>> type="popup" position="belowleft" class="tc-drop-down">
	<$list filter=<<palettes>>>
	  <$button class="tc-btn-invisible">
	    {{!!name}}
	    <$action-setfield $tiddler="$:/palette" text={{!!title}}/>
	  </$button>
	</$list>
        <$button class="tc-btn-invisible">
          More Palettes
          <$action-navigate $to="$:/More Palettes"/>
        </$button>
      </$reveal>

    </$button>
  </$vars>
</span>
"},"$:/themes/nico/notebook/ui/Buttons/menu":{"title":"$:/themes/nico/notebook/ui/Buttons/menu","type":"text/vnd.tiddlywiki","text":"<$reveal state="$:/state/notebook-sidebar" type="match" text="yes" default="no" retain="yes" animate="no">
  <$button class="tc-btn-invisible sidebar-toggle open" tooltip="Toggle menu">
    <$action-setfield $tiddler="$:/state/notebook-sidebar" text="no"/>
    <$list filter="[[$:/state/lithic/tweak-sidebar]get[text]match[yes]]" variable="ignore">
      <$action-setfield $tiddler="$:/state/lithic/tweak-sidebar" text="no"/>
      <$list filter="[[$:/temp/edit-site-title]!is[missing]]" variable="ignore"><$action-setfield $tiddler="$:/SiteTitle" text={{$:/temp/edit-site-title}}/></$list>
      <$list filter="[[$:/temp/edit-site-subtitle]!is[missing]]" variable="ignore"><$action-setfield $tiddler="$:/SiteSubtitle" text={{$:/temp/edit-site-subtitle}}/></$list>
    </$list>
    {{$:/themes/nico/notebook/images/bars}}
  </$button>
</$reveal>

<$reveal type="nomatch" state="$:/state/notebook-sidebar" text="yes">
  <$button class="tc-btn-invisible sidebar-toggle" tooltip="Toggle menu">
    <$action-setfield $tiddler="$:/state/notebook-sidebar" text="yes"/>
    {{$:/themes/nico/notebook/images/bars}}
  </$button>
</$reveal>"},"$:/themes/nico/notebook/ui/Search":{"title":"$:/themes/nico/notebook/ui/Search","text":"\whitespace trim
